using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Diagnostics;
namespace Lumina {
    public partial class Controller {
        readonly BoardEditHistory editHistory=new BoardEditHistory();
        public BoardEditState BeginBoardEdit(){return BoardEditState.Capture(Prefs);}
        public void EndBoardEdit(BoardEditState before,string label){editHistory.Remember(before,Prefs,label);Save();}
        public bool CanRedoBoard{get{return editHistory.CanRedo;}}
        public string UndoLabel{get{return editHistory.UndoLabel;}}
        public void UndoBoard(){string label=editHistory.Undo(Prefs);if(label==null)return;Board.FinishSelection();Refresh();Board.SetStatus("已撤销："+label);}
        public void RedoBoard(){string label=editHistory.Redo(Prefs);if(label==null)return;Board.FinishSelection();Refresh();Board.SetStatus("已重做："+label);}
        public void TransferEntries(string[] paths,string from,string to){var before=BeginBoardEdit();int count=FeatureRules.Transfer(Prefs,paths,from,to);EndBoardEdit(before,from=="全部"?"添加到分组":"移动分组");Board.FinishSelection();Refresh();Board.SetStatus("已处理 "+count+" 个入口 · 可按 Ctrl+Z 撤销");}
        public void ReorderEntry(string path,Entry target){var moved=Prefs.Apps.FirstOrDefault(a=>string.Equals(a.Path,path,StringComparison.OrdinalIgnoreCase));if(moved==null||moved==target)return;var before=BeginBoardEdit();int index=Prefs.Apps.IndexOf(target);Prefs.Apps.Remove(moved);Prefs.Apps.Insert(Math.Min(index,Prefs.Apps.Count),moved);EndBoardEdit(before,"调整图标顺序");Refresh();}
        void FlushBackupState(){Store.Save(Prefs);if(widgets==null)RefreshWidgets();}
        public void ExportFullBackup(){bool previous=Board.ModalBusy;Board.ModalBusy=true;try{var pick=new Microsoft.Win32.SaveFileDialog{FileName="Lumina_完整备份_"+DateTime.Now.ToString("yyyyMMdd_HHmm")+".gbbackup",Filter="Lumina 完整备份|*.gbbackup"};if(pick.ShowDialog(OwnerWindow)!=true)return;FlushBackupState();BackupFiles.Create(Store.Folder,pick.FileName);MessageBox.Show(OwnerWindow,"布局、分组、快捷键、组件、便签、外观方案与自定义图标已备份。","备份完成");}catch(Exception ex){Store.Log(ex);MessageBox.Show(OwnerWindow,ex.Message,"备份失败");}finally{Board.ModalBusy=previous;}}
        public void RestoreFullBackup(){if(settingsWindow!=null)settingsWindow.Close();bool previous=Board.ModalBusy;Board.ModalBusy=true;try{var pick=new Microsoft.Win32.OpenFileDialog{Filter="Lumina 完整备份|*.gbbackup"};if(pick.ShowDialog(OwnerWindow)!=true)return;BackupFiles.Read(pick.FileName);if(MessageBox.Show(OwnerWindow,"恢复此备份中的布局、分组、快捷键与便签？\n当前配置会先自动保存为恢复前备份。开机启动开关按当前电脑保留。","恢复完整备份",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;FlushBackupState();string safety=Path.Combine(Store.Folder,"backups","恢复前_"+DateTime.Now.ToString("yyyyMMdd_HHmmss_fff")+".gbbackup");Directory.CreateDirectory(Path.GetDirectoryName(safety));BackupFiles.Create(Store.Folder,safety);var oldKeys=Prefs.Hotkeys.Select(k=>k.Copy()).ToList();BackupFiles.Restore(pick.FileName,Store.Folder);Prefs=Store.Load(false);DesktopPersistence.SetDesktopOnly(Prefs.AllDesktopLayer);string error;bool keys=Dock.ApplyHotkeys(Prefs.Hotkeys,out error);if(!keys)Prefs.Hotkeys=oldKeys;editHistory.Clear();bool visible=Board.IsVisible;Refresh();RefreshTrayMenu();if(visible)Board.Open();MessageBox.Show(OwnerWindow,"配置已恢复。恢复前备份已保存到：\n"+safety+(keys?"":"\n快捷键与系统冲突，已保留原快捷键："+error),"恢复完成");}catch(Exception ex){Store.Log(ex);MessageBox.Show(OwnerWindow,ex.Message,"恢复失败");}finally{Board.ModalBusy=previous;}}
        static BitmapSource CreatorImage(string key,bool thumbnail=false){if(thumbnail)return ThumbnailImages.Read(CreatorAssets.Read(key),960);using(var stream=new MemoryStream(CreatorAssets.Read(key),false)){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();return image;}}
        void ShowCreatorImage(Window owner,string key,string title){var w=FeatureUi.Dialog(title,owner,680,850);w.ResizeMode=ResizeMode.CanResize;var root=new DockPanel{Margin=new Thickness(18)};var label=new TextBlock{Text="感谢你的支持 · 森霖sama",Foreground=Brushes.White,FontSize=15,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,12,0,0)};DockPanel.SetDock(label,System.Windows.Controls.Dock.Bottom);root.Children.Add(label);root.Children.Add(new Image{Source=CreatorImage(key),Stretch=Stretch.Uniform});w.Content=root;w.ShowDialog();}
        public void BuildCreatorSupport(StackPanel panel,Window owner){panel.Children.Add(new TextBlock{Text="由 森霖sama 制作",Foreground=Brushes.White,FontSize=25,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,10,0,12)});panel.Children.Add(new TextBlock{Text="谢谢你的支持与陪伴，也谢谢每一次认真反馈。你的鼓励，会帮助我继续打磨 Lumina，让桌面更舒服、更好用。",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightGray,FontSize=14,LineHeight=24,Margin=new Thickness(0,0,0,16)});var cards=new WrapPanel();panel.Children.Add(cards);Action<string,string> add=(key,title)=>{var body=new StackPanel();body.Children.Add(new TextBlock{Text=title,Foreground=Brushes.White,FontSize=17,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,12)});var image=new Image{Source=CreatorImage(key,true),Height=300,Stretch=Stretch.Uniform,Cursor=System.Windows.Input.Cursors.Hand,ToolTip="点击查看大图"};image.MouseLeftButtonUp+=(s,e)=>ShowCreatorImage(owner,key,title);body.Children.Add(image);body.Children.Add(FeatureUi.Button("查看大图",()=>ShowCreatorImage(owner,key,title)));cards.Children.Add(new Border{Width=238,CornerRadius=new CornerRadius(18),Padding=new Thickness(14),Margin=new Thickness(0,0,14,14),Background=Polish.Color("#242936"),BorderBrush=Polish.Color("#394151"),BorderThickness=new Thickness(1),Child=body});};try{add("Wechat","微信支付");add("Alipay","支付宝");}catch(Exception ex){cards.Children.Clear();Store.Log(ex);panel.Children.Add(new TextBlock{Text="收款资源校验失败，已停止显示。请重新解压原版程序。",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightGray,Margin=new Thickness(0,12,0,12)});}panel.Children.Add(new TextBlock{Text="随心支持，一份鼓励就很珍贵。感谢你让这份创作继续生长。",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightGray,Margin=new Thickness(0,8,0,12),FontSize=13});}
    }
}
